/**
 * Known per-chain protocol addresses (from `docs/ROBINHOOD_CHAIN.md`, stored EIP-55 checksummed),
 * the Pons V2 launchpad contracts on Robinhood Chain mainnet, and the Beagle deployment lookup
 * (`CreditDesk`, token, price source) backed by `deployments.generated.ts`.
 *
 * No file-system or environment access: deployments come from `deployments.generated.ts`
 * (generated by `node scripts/sync-deployments.mjs` from `contracts/deployments/*.json`). Env
 * overrides (`CREDIT_DESK_ADDRESS`, `VITE_CREDIT_DESK_ADDRESS`, …) are applied by the consumer
 * through {@link resolveDeployment}, where the zero address and the empty string count as unset.
 *
 * @module addresses
 */
import { getAddress, isAddress, type Address } from 'viem';
import { ANVIL_CHAIN_ID, ROBINHOOD_CHAIN_ID, ROBINHOOD_TESTNET_CHAIN_ID } from './chains.js';
import { DEPLOYMENTS } from './deployments.generated.js';

/** The zero address (`address(0)`). */
export const ZERO_ADDRESS: Address = '0x0000000000000000000000000000000000000000';

/** The conventional burn address used by `CreditDesk` when the token has no `burn` (SPEC §1). */
export const DEAD_ADDRESS: Address = '0x000000000000000000000000000000000000dEaD';

/** Third-party protocol addresses known for a chain (all optional: anvil has none). */
export interface ChainAddresses {
  weth9?: Address;
  uniswapV3Factory?: Address;
  uniswapV3PositionManager?: Address;
  uniswapV3SwapRouter02?: Address;
  uniswapV3QuoterV2?: Address;
  uniswapV3TickLens?: Address;
  uniswapV3PoolInitCodeHash?: `0x${string}`;
  uniswapV2Factory?: Address;
  uniswapV2Router02?: Address;
  uniswapV2PairInitCodeHash?: `0x${string}`;
  uniswapV4PoolManager?: Address;
  uniswapV4PositionManager?: Address;
  uniswapV4Quoter?: Address;
  uniswapV4StateView?: Address;
  universalRouter?: Address;
  permit2?: Address;
  uniswapInterfaceMulticall?: Address;
}

